// Inlines Leaflet's JS/CSS into a TS module so the map works without a CDN.
// Run: node scripts/gen-leaflet.js   (output is committed; rerun only if you upgrade leaflet)
const fs = require('fs');
const path = require('path');
const dist = path.join(__dirname, '..', 'node_modules', 'leaflet', 'dist');
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8');
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8');
const out =
  '// AUTO-GENERATED by scripts/gen-leaflet.js — do not edit.\n' +
  `export const LEAFLET_JS = ${JSON.stringify(js)};\n` +
  `export const LEAFLET_CSS = ${JSON.stringify(css)};\n`;
fs.writeFileSync(path.join(__dirname, '..', 'src', 'leafletAssets.ts'), out);
console.log('wrote src/leafletAssets.ts', out.length, 'bytes');
